package com.mantou.salesdialer.contacts;
import android.app.Activity;import android.os.Bundle;import android.util.AtomicFile;import android.widget.TextView;import org.json.*;
import java.io.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
import com.mantou.salesdialer.contacts.PhoneIntakeModel.DataClass;
/** Fixed metadata codec and disabled-route checks. Never writes READY or supplies a phone port. */
public final class PilotReadinessCheckActivity extends Activity {
 private int checks;private interface Action{void run()throws Exception;}
 private void check(boolean v){checks++;if(!v)throw new IllegalStateException("READINESS_ASSERTION_"+checks);}
 private void reject(Action a){checks++;try{a.run();}catch(Exception expected){return;}throw new IllegalStateException("MALFORMED_PERMIT_ACCEPTED");}
 private JSONObject copy(JSONObject j)throws Exception{return new JSONObject(j.toString());}
 private byte[] bytes(JSONObject j){return j.toString().getBytes(StandardCharsets.UTF_8);}
 private void runChecks()throws Exception{
  long due=Instant.parse("2026-10-19T01:00:00Z").toEpochMilli();var p=new PilotPermit(DataClass.LOCAL_PHONE_INTAKE,"a".repeat(32),"LOCAL-TARGET-"+"b".repeat(32),1,"c".repeat(64),"d".repeat(32),new WorkspaceTimerModel.Ticket(1,due,1000,"fixture-boot","e".repeat(32)));var valid=PilotPhoneRuntime.encode(p,"READY");check(PilotPhoneRuntime.decode(PilotPhoneRuntime.parseEnvelope(bytes(valid))).fingerprint().equals(p.fingerprint()));check(PilotPhoneRuntime.parseEnvelope(bytes(new JSONObject().put("schema",1).put("state","DISABLED"))).getString("state").equals("DISABLED"));
  for(String field:List.of("contactRevision","version","dueWall","dueElapsed")){JSONObject textValue=copy(valid).put(field,"1");reject(()->PilotPhoneRuntime.parseEnvelope(bytes(textValue)));JSONObject fraction=copy(valid).put(field,1.5);reject(()->PilotPhoneRuntime.parseEnvelope(bytes(fraction)));}
  for(Object schema:List.of("1",2)){JSONObject j=copy(valid).put("schema",schema);reject(()->PilotPhoneRuntime.parseEnvelope(bytes(j)));}reject(()->PilotPhoneRuntime.parseEnvelope(valid.toString().replace("\"schema\":1","\"schema\":1.0").getBytes(StandardCharsets.UTF_8)));JSONObject extra=copy(valid).put("number","not-a-number");reject(()->PilotPhoneRuntime.parseEnvelope(bytes(extra)));JSONObject format=copy(valid).put("kind","FORMAT_FIXTURE");reject(()->PilotPhoneRuntime.parseEnvelope(bytes(format)));JSONObject wrongState=copy(valid).put("state","ENABLED_FOREVER");reject(()->PilotPhoneRuntime.parseEnvelope(bytes(wrongState)));JSONObject disabledExtra=new JSONObject().put("schema",1).put("state","DISABLED").put("token","ignored");reject(()->PilotPhoneRuntime.parseEnvelope(bytes(disabledExtra)));reject(()->PilotPhoneRuntime.parseEnvelope(new byte[4097]));
  JSONObject before=PilotPhoneRuntime.snapshot(this);if(before.getBoolean("armed")||before.getBoolean("sending"))throw new IllegalStateException("DISABLED_PILOT_REQUIRED");String digest;try(PhoneIntakeStore s=PhoneIntakeStore.open(this,DataClass.LOCAL_PHONE_INTAKE)){digest=s.dataDigest();}PilotPhoneRuntime.fire(this,"0".repeat(32));try(PhoneIntakeStore s=PhoneIntakeStore.open(this,DataClass.LOCAL_PHONE_INTAKE)){check(s.dataDigest().equals(digest));}JSONObject after=PilotPhoneRuntime.snapshot(this);check(!after.getBoolean("armed")&&!after.getBoolean("sending"));
 }
 @Override public void onCreate(Bundle saved){super.onCreate(saved);TextView text=new TextView(this);text.setText("检查配置与停用状态，不授权或拨打电话。");setContentView(text);new Thread(()->{JSONObject report=new JSONObject();boolean passed=false;try{runChecks();report.put("decision","PASSED");passed=true;}catch(Exception e){try{String code=e.getMessage();report.put("decision","FAILED").put("errorCode",code!=null&&code.matches("[A-Z_0-9]+")?code:"READINESS_CHECK_FAILED");}catch(Exception ignored){}}try{report.put("source","FIXED_PILOT_METADATA_AND_DISABLED_ROUTE").put("assertions",checks).put("actualPhoneCalls",0);AtomicFile f=new AtomicFile(new File(getFilesDir(),"pilot-readiness-check.json"));FileOutputStream out=f.startWrite();out.write(report.toString().getBytes(StandardCharsets.UTF_8));f.finishWrite(out);}catch(Exception e){passed=false;}boolean ok=passed;runOnUiThread(()->text.setText(ok?"配置和停用路径检查通过，没有拨号。":"准备检查未通过，请保留记录。"));},"pilot-readiness-check").start();}
}
